function clearHighlights() {
  for (var i = 0; i < N; i++) {
    barEls[i].classList.remove('compare');
    barEls[i].classList.remove('swap');
  }
}

function swapValues(i, j) {
  var t = state.values[i];
  state.values[i] = state.values[j];
  state.values[j] = t;
}

function doStep() {
  if (state.done || !gen) return;
  clearHighlights();
  var r = gen.next();
  if (r.done) {
    finish();
    return;
  }
  var a = r.value;
  state.comparisons++;
  markCompare(a.i, a.j);
  if (a.swap) {
    swapValues(a.i, a.j);
    state.swaps++;
    markSwap(a.i, a.j);
  }
  if (a.shift) {
    var k = a.from;
    var v = state.values[k];
    for (var m = k; m > a.to; m--) {
      state.values[m] = state.values[m - 1];
    }
    state.values[a.to] = v;
    state.swaps++;
    markSwap(a.to, a.from);
  }
  if (a.sorted) {
    for (var s = 0; s < a.sorted.length; s++) markSorted(a.sorted[s]);
  }
  render();
}

function finish() {
  state.done = true;
  state.playing = false;
  gen = null;
  if (timer) { clearTimeout(timer); timer = null; }
  for (var i = 0; i < N; i++) markSorted(i);
  clearHighlights();
  render();
  updateButtons();
}

function tick() {
  if (!state.playing || state.done) return;
  doStep();
  if (state.playing && !state.done) {
    timer = setTimeout(tick, delayMs());
  }
}

function play() {
  if (state.done) return;
