function* bubbleGen(a) {
  var n = a.length;
  for (var i = 0; i < n - 1; i++) {
    var swapped = false;
    for (var j = 0; j < n - 1 - i; j++) {
      var cmp = a[j] > a[j + 1];
      yield { i: j, j: j + 1, swap: cmp, sorted: [] };
      if (cmp) {
        swapped = true;
      }
    }
    yield { i: null, j: null, swap: false, sorted: [n - 1 - i] };
    if (!swapped) break;
  }
}

function* insertionGen(a) {
  var n = a.length;
  yield { i: null, j: null, swap: false, sorted: [0] };
  for (var i = 1; i < n; i++) {
    var j = i - 1;
    while (j >= 0) {
      yield { i: j, j: j + 1, swap: a[j] > a[j + 1], sorted: [] };
      if (a[j] > a[j + 1]) {
        j--;
      } else {
        break;
      }
    }
    if (j >= 0) {
      yield { i: null, j: null, swap: false, shift: { from: i, to: j + 1 }, sorted: [] };
    }
  }
}

function* quickGen(a) {
  var n = a.length;
  var stack = [0];
  while (stack.length) {
    var lo = stack.pop();
    var hi = lo + n - 1;
    if (hi - lo + 1 <= 1) {
      yield { i: null, j: null, swap: false, sorted: [lo] };
      continue;
    }
    var p = partition(a, lo, hi);
    yield { i: null, j: null, swap: false, sorted: [p] };
    if (p - lo > 1) stack.push(p - (p - lo));
    if (hi - p > 1) stack.push(p + 1);
  }
}

function* partition(a, lo, hi) {
  var pivot = a[hi];
  var i = lo - 1;
  for (var j = lo; j < hi; j++) {
    yield { i: j, j: hi, swap: false, sorted: [] };
    if (a[j] < pivot) {
      i++;
      yield { i: i, j: j, swap: true, sorted: [] };
    }
  }
  yield { i: i + 1, j: hi, swap: true, sorted: [] };
  return i + 1;
}

